#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    int n = 0;
    double s = 0.0;
    if (std::cin >> n >> s && n >= 3 && s > 0) {
        const double PI = std::acos(-1.0);
        double area = (n * s * s) / (4.0 * std::tan(PI / n));
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "The area of the polygon is " << area << "\n";
    }
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>

int main() {
    char ch = ' ';
    if (std::cin >> ch) {
        int asciiCode = static_cast<int>(ch);
        std::cout << "ASCII: " << asciiCode << "\n";
        char upper = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
        std::cout << "Upper: " << upper << "\n";
    }
    std::string s;
    if (std::cin >> s && !s.empty()) {
        std::cout << "String: " << s << " length: " << s.length() << " last: " << s.back() << "\n";
    }
    return 0;
}
